import { isbot } from "isbot";
import { renderToReadableStream } from "react-dom/server";
import {
  ServerRouter,
  type EntryContext,
  type HandleErrorFunction,
  type RouterContextProvider,
} from "react-router";
import { ContainerProvider } from "@stackra/container/react";
import { NonceProvider } from "@stackra/csp/react";
import { containerContext, nonceContext, reporterContext } from "./context";

/** edge.config.ts streamTimeoutMs: React Router rejects pending loader promises after this. */
export const streamTimeout = 5_000;

/** edge.config.ts botsWaitForAll. */
const BOTS_WAIT_FOR_ALL = true;

/** Renders one document request into a stream. */
export default async function handleRequest(
  request: Request,
  responseStatusCode: number,
  responseHeaders: Headers,
  routerContext: EntryContext,
  context: RouterContextProvider,
) {
  const nonce = context.get(nonceContext);
  const reporter = context.get(reporterContext);
  // a second past the router's own timeout, so its rejections flush before the stream is cut
  const signal = AbortSignal.any([request.signal, AbortSignal.timeout(streamTimeout + 1_000)]);
  let status = responseStatusCode;
  // a shell error rejects the render and React Router passes it to handleError; report later ones
  let shellRendered = false;

  const body = await renderToReadableStream(
    <ContainerProvider container={context.get(containerContext)}>
      <NonceProvider value={nonce}>
        <ServerRouter context={routerContext} url={request.url} nonce={nonce} />
      </NonceProvider>
    </ContainerProvider>,
    {
      signal,
      nonce,
      onError(error: unknown) {
        status = 500;
        if (shellRendered && !signal.aborted) reporter.report(error);
      },
    },
  );
  shellRendered = true;
  if (BOTS_WAIT_FOR_ALL && isbot(request.headers.get("user-agent") ?? "")) await body.allReady;

  responseHeaders.set("Content-Type", "text/html; charset=utf-8");
  return new Response(body, { status, headers: responseHeaders });
}

/** Loader, action and render errors on the server: once each, and never for an aborted request. */
export const handleError: HandleErrorFunction = (error, { request, context }) => {
  if (!request.signal.aborted) context.get(reporterContext).report(error);
};
